head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.selectedGrdNum = 0;
scwin.isFirstLoad = false;
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "", scwin.select_gubun = "";
scwin.trsCnt = 0, scwin.trsTotalCnt = 0, scwin.trsErrCnt = 0;
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명(종목명)
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값(종목코드값)
            scwin.select_gubun = (arrPar.length >= 7 ? arrPar[6] : ""); //  구분값

        }
        await scwin.getRsnCd();

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        await scwin.newOnload(); // 신규작성시 호출

        dts_Rsn.removeRow(1);
        scwin.setIsuCdBtnShow(scwin.select_gubun);
        $c.libRoundPanel.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08056_new.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "N");
        scwin.trsErrCnt++;
        if (scwin.trsCnt === scwin.trsTotalCnt && scwin.trsErrCnt > 0) {
            $c.lce.fn_alertMsg('F');
            if (buttonSet.status === "D") {
                // 삭제처리의 응답인 경우
                dts_Isu_Temp.setBroadcast(false);
                for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
                    if (dts_Isu_Temp.getCellData(i, "STATUS") === "Y") {
                        dts_Isu_Temp.removeRow(i);
                    }
                }
                dts_Isu_Temp.setBroadcast(true, true);
            } else {

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08056_new.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        dts_Isu_Temp.setCellData(scwin.trsCnt, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "Y");
        if (scwin.trsCnt === scwin.trsTotalCnt) {
            $c.lce.fn_alertMsg('S');
            scwin.parentRefresh(); // 목록 다시 조회

            if (dts_Isu_Temp.getRowCount() === 1) {
                scwin.selectGridRow(1);
            }
            if (buttonSet.status === "I") {
                // 저장처리의 응답인 경우
                buttonSet.setUpdateStatus();
                scwin.setIsuCdBtnShow(1);
            } else if (buttonSet.status === "D") {
                // 삭제처리의 응답인 경우
                await $c.win.closePopup();
            } else {
                buttonSet.setUpdateStatus();
                // fn_search();

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08056_new.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08056_new.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_Temp_OnLoadError
 * @description dts_Isu_Temp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_Temp_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu_Temp);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08056_new.dts_Isu_Temp_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        dts_Isu.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08056_new.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Isu_Temp_OnLoadCompleted
 * @description dts_Isu_Temp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_Temp_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.insertRow();
        }

        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
        scwin.isFirstLoad = true;
        if (scwin.fr_bz_procs_no === "") {
            cmb_Rsn_Cd.BindColVal = "21";
            txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
            scwin.setRemk();
        } else {
            cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD");
        }
        scwin.isFirstLoad = false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08056_new.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08056_new.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_onselchange2
 * @description cmb Rsn Cd onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_onselchange2 = function() {
    try {
        if (scwin.isFirstLoad) return;
        txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        scwin.setRemk();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08056_new.cmb_Rsn_Cd_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_Rsn_Cd_OnSelected
 * @description cmb Rsn Cd On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_Rsn_Cd_OnSelected = function() {

};

/**
 * @method
 * @name img_SetIsuCd_onclick
 * @description 「종목선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsu;
        scwin.setPar = scwin.setParIsu;
        $c.lce.fn_PopFindEtnCode();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08056_new.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name grid_1_OnClick
 * @description grid_1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grid_1_OnClick = function(row, colid) {
    try {
        scwin.selectGridRow(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08056_new.grid_1_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    /* useupdate를 false로 지정함. */
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.select_gubun === "1") {
        const sbmOptions = {
            id : "sbm_dts_Isu_Temp",
            action : "/etn/EtnCodeAct.do",
            ref : "",
            target : "dts_Isu_Temp=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        const sbmOptions = {
            id : "sbm_dts_Isu",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Isu.insertRow();
        const sbmOptions2 = {
            id : "sbm_dts_Isu_Temp",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu_Temp=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name getRsnCd
 * @description get Rsn Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getRsnCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_Rsn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description 종목별 처리를 위해 매번 업무처리 번호를 세팅함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // 종목별 처리를 위해 매번 업무처리 번호를 세팅함
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "COM_NM", scwin.Isur_nm);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "WRT_DD", $c.ut.cGetToday("yyyymmdd"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "INFO_CONTN_TP_CD", "9"); // 9 ETN상장폐지예고

    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_711 + ",DIV_IDX[0]=" + DIV_IDX_ETN_DELLIST_MST_INFO + ",DIV_IDX[1]=" + DIV_IDX_ETN_DELLIST_DTL_INFO
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/etn/EtnMktAct.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsu
 * @description get Par Isu 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.getParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.select_gubun;
    $c.stf.copyDataSet(dts_Isu_Temp, param_dts);
};

/**
 * @method
 * @name setParIsu
 * @description set Par Isu 처리
 * @param {*} param_dts param_dts
 * @returns {void}
 * @hidden N
 */
scwin.setParIsu = function(param_dts) {
    $c.stf.copyDataSet(param_dts, dts_Isu_Temp);
    for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        /*ORG SRC: dts_Isu_Temp.NameString(i, "STATUS") = "N";*/
        X = "N";
    }

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (dts_Isu_Temp.getRowCount() === 0) {
        await $c.win.alert("[예고종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_GrndRegulContn, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulContn, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};

/**
 * @method
 * @name copyDts
 * @description copy Dts 처리
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.copyDts = function(index) {
    // dts_Isu.Reset();
    if (dts_Isu.getRowCount() === 0) {
        dts_Isu.insertRow();
    }
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Isu.setCellData(1, "ISU_CD", dts_Isu_Temp.getCellData(index, "ISU_CD"));
    dts_Isu.setCellData(1, "ISU_NM", dts_Isu_Temp.getCellData(index, "ISU_NM"));
    dts_Isu.setCellData(1, "ISUR_CD", dts_Isu_Temp.getCellData(index, "ISUR_CD"));
    dts_Isu.setCellData(1, "ISUR_NM", dts_Isu_Temp.getCellData(index, "ISUR_NM"));
    dts_Isu.setCellData(1, "COM_NM", dts_Isu_Temp.getCellData(index, "COM_NM"));
    dts_Isu.setCellData(1, "LSTTRD_DD", dts_Isu_Temp.getCellData(index, "LSTTRD_DD"));
    dts_Isu.setCellData(1, "EXP_DD", dts_Isu_Temp.getCellData(index, "EXP_DD"));
    scwin.Isur_cd = dts_Isu_Temp.getCellData(index, "ISUR_CD");
    scwin.Isur_nm = dts_Isu_Temp.getCellData(index, "COM_NM");
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess('I')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getRowCount();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        dts_Isu_Temp.setBroadcast(false);
        for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
            scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
            scwin.copyDts(i);
            if (scwin.fr_bz_procs_no.length !== 14) {
                await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            } else {
                scwin.trsIdx = TRS_IDX_INSERT;
                dts_Isu_Temp.setCellData(i, "STATUS", "N");
                scwin.trsCnt++;
                await scwin.saveTrs();
            }
        }
        dts_Isu_Temp.setBroadcast(true, true);
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if ($c.en.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lce.fn_isProcess('U')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getRowCount();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        dts_Isu_Temp.setBroadcast(false);
        for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
            scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
            // alert('fr_bz_procs_no : ' + fr_bz_procs_no);

            scwin.copyDts(i);
            dts_Isu_Temp.setCellData(i, "STATUS", "N");
            scwin.trsCnt++;
            await scwin.saveTrs();
        }
        dts_Isu_Temp.setBroadcast(true, true);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lce.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.trsTotalCnt = dts_Isu_Temp.getRowCount();
    scwin.trsCnt = 0;
    scwin.trsErrCnt = 0;
    dts_Isu_Temp.setBroadcast(false);
    for (let i = 1; i <= dts_Isu_Temp.getRowCount(); i++) {
        scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
        // alert('fr_bz_procs_no : ' + fr_bz_procs_no);

        scwin.copyDts(i);
        dts_Isu_Temp.setCellData(i, "STATUS", "N");
        scwin.trsCnt++;
        await scwin.saveTrs();
    }
    dts_Isu_Temp.setBroadcast(true, true);
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (scwin.selectedGrdNum === 0) {
        await $c.win.alert('종목을 선택해 주세요! ');
        return;
    }
    scwin.copyDts(scwin.selectedGrdNum);
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        // cmb_Rsn_Cd.BindColVal == "202"
        if (cmb_Rsn_Cd.BindColVal === "21") {
            arr[0] = "68352A";
        } else if (cmb_Rsn_Cd.BindColVal === "22") {
            arr[0] = "68352B";
        } else if (cmb_Rsn_Cd.BindColVal === "23") {
            arr[0] = "68352C";
        } else if (cmb_Rsn_Cd.BindColVal === "24") {
            arr[0] = "68352D";
        }
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        arr[5] = dts_Isu_Temp.getCellData(scwin.selectedGrdNum, "ISU_NM");
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ADVNOTI_RSN_TP_CD_NM", cmb_Rsn_Cd.getText());
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 15;
    const hgt = 785 + 40;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

