/**
 * @method
 * @name setRemk
 * @description set Remk 처리
 * @returns {void}
 * @hidden N
 */
scwin.setRemk = function() {
    if (cmb_Rsn_Cd.BindColVal === "21" || cmb_Rsn_Cd.BindColVal === "22") {
        txa_Remk.Text = "상기 종목은 1개월 이내에 유동성공급 계획의 제출 또는 다른 유동성공급자와 유동성공급 계약을\r\n";
        txa_Remk.Text += "체결하지 않을 경우 상장폐지됨을 알려드립니다.\r\n";
        // txa_Remk.Text = "상기 종목은 유동성공급자를 1개월 이내에 교체하지 않을 경우 상장폐지됨을 알려드립니다.\r\n";

    } else if (cmb_Rsn_Cd.BindColVal === "23") {
        txa_Remk.Text = "상기 종목은 발행회사의 영업용순자본비율 150%가 3개월 지속될 경우 또는\r\n";
        txa_Remk.Text += "해당 기간중에라도 120% 미만이 발생할 경우 즉시 상장폐지됨을 알려드립니다.\r\n";
    } else if (cmb_Rsn_Cd.BindColVal === "10") {
        txa_Remk.Text = "상기 상장지수증권은 만기가 1개월 남았음을 알려드립니다. \r\n";
    } else if (cmb_Rsn_Cd.BindColVal === "24") {
        txa_Remk.Text = "상기 상장지수증권은 발행사의 신청에 따라 0000년 00월 00일 상장폐지 될 예정임을 알려드립니다.\r\n";
        txa_Remk.Text += "(단, 상장폐지 전일 자진 상장폐지 요건(LP 보유비중 95% 이상) 충족 필요)";
    }
};

/**
 * @method
 * @name setIsuCdBtnShow
 * @description set Isu Cd Btn Show 처리
 * @param {*} initTyp initTyp
 * @returns {void}
 * @hidden N
 */
scwin.setIsuCdBtnShow = function(initTyp) {
    if (initTyp === "1" || scwin.fr_bz_procs_no !== "") {
        img_SetIsuCd.setBackgroundImage("../img/btn_isu_select_d.gif");
        img_SetIsuCd.setDisabled(true);
    } else {
        img_SetIsuCd.setBackgroundImage("../img/btn_isu_select.gif");
        img_SetIsuCd.setDisabled(false);
    }
};

